"""Zero-build browser surface for the RASAi SaaS pilot.

The UI is intentionally dependency-free. It consumes the tenant-aware HTTP API and
never reimplements audit, scoring, Search Intelligence or comparison logic.
"""
from __future__ import annotations

PILOT_UI_HTML = r'''<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>RASAi · SaaS Pilot</title>
<style>
:root{font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#172033;background:#f4f6f9;line-height:1.45}*{box-sizing:border-box}body{margin:0}.shell{min-height:100vh;display:grid;grid-template-columns:250px 1fr}.side{background:#111827;color:#f8fafc;padding:26px 20px;position:sticky;top:0;height:100vh}.brand{font-size:1.35rem;font-weight:800;letter-spacing:.01em}.sub{color:#94a3b8;font-size:.82rem;margin-top:3px}.nav{display:grid;gap:6px;margin-top:28px}.nav button{appearance:none;border:0;background:transparent;color:#cbd5e1;text-align:left;padding:10px 12px;border-radius:8px;font:inherit;cursor:pointer}.nav button:hover,.nav button.active{background:#1f2937;color:white}.side-note{position:absolute;left:20px;right:20px;bottom:22px;color:#94a3b8;font-size:.76rem}.main{padding:28px 32px 60px;min-width:0}.top{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;margin-bottom:22px}.top h1{font-size:1.6rem;margin:0}.muted{color:#667085}.status{padding:7px 10px;border-radius:999px;background:#e5e7eb;font-size:.78rem;white-space:nowrap}.status.ok{background:#dcfce7;color:#166534}.status.warn{background:#fef3c7;color:#92400e}.selectors{display:grid;grid-template-columns:repeat(5,minmax(130px,1fr));gap:10px;background:white;padding:14px;border:1px solid #e4e7ec;border-radius:12px;margin-bottom:20px}.selectors label,.form-grid label{display:grid;gap:5px;font-size:.76rem;color:#667085}.selectors select,.form-grid select,.form-grid input,.form-grid textarea{width:100%;border:1px solid #d0d5dd;background:#fff;border-radius:8px;padding:8px 9px;color:#172033}.panel{display:none}.panel.active{display:block}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:16px}.card{background:white;border:1px solid #e4e7ec;border-radius:12px;padding:16px;min-width:0}.metric{font-size:1.7rem;font-weight:750;margin-top:5px}.card h2,.card h3{margin:0 0 10px}.card h2{font-size:1.03rem}.section-grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(280px,1fr);gap:14px}.table-wrap{overflow:auto;border:1px solid #e4e7ec;border-radius:10px;background:#fff}table{width:100%;border-collapse:collapse;font-size:.82rem}th,td{text-align:left;padding:10px 11px;border-bottom:1px solid #eef0f3;vertical-align:top}th{font-size:.72rem;text-transform:uppercase;letter-spacing:.04em;color:#667085;background:#f9fafb}tr:last-child td{border-bottom:0}.pill{display:inline-block;border-radius:999px;padding:3px 7px;background:#eef2f6;font-size:.7rem}.pill.good{background:#dcfce7;color:#166534}.pill.bad{background:#fee2e2;color:#991b1b}.pill.wait{background:#fef3c7;color:#92400e}.btn{appearance:none;border:1px solid #d0d5dd;background:white;border-radius:8px;padding:7px 10px;font:inherit;font-size:.8rem;cursor:pointer}.btn:hover{background:#f8fafc}.btn.primary{background:#172033;border-color:#172033;color:white}.btn.danger{color:#b42318}.actions{display:flex;gap:6px;flex-wrap:wrap}.empty{padding:22px;color:#667085;text-align:center}.notice{padding:12px 14px;border-radius:10px;background:#eff6ff;color:#1e3a8a;font-size:.82rem;margin-bottom:14px}.error{background:#fef2f2;color:#991b1b}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.form-grid .full{grid-column:1/-1}.form-actions{margin-top:12px;display:flex;gap:8px;flex-wrap:wrap}.mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.76rem;word-break:break-all}.detail{white-space:pre-wrap;background:#f8fafc;border:1px solid #e4e7ec;border-radius:8px;padding:10px;font-size:.78rem;min-height:60px}@media(max-width:1100px){.selectors{grid-template-columns:repeat(2,minmax(0,1fr))}.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.section-grid{grid-template-columns:1fr}}@media(max-width:760px){.shell{grid-template-columns:1fr}.side{position:relative;height:auto}.side-note{display:none}.nav{grid-template-columns:repeat(3,1fr);margin-top:14px}.main{padding:20px 14px}.top{display:block}.status{display:inline-block;margin-top:8px}.selectors,.grid,.form-grid{grid-template-columns:1fr}.form-grid .full{grid-column:auto}}
</style>
</head>
<body>
<div class="shell">
<aside class="side">
  <div class="brand">RASAi</div><div class="sub">Search &amp; AI Readiness Auditor</div>
  <div class="nav" id="nav">
    <button class="active" data-panel="overview">Visão geral</button>
    <button data-panel="audits">Auditorias</button>
    <button data-panel="search">Search Intelligence</button>
    <button data-panel="deployments">Deployments</button>
    <button data-panel="jobs">Execuções</button>
    <button data-panel="usage">Uso e custo</button>
  </div>
  <div class="side-note">Piloto Web · projeção sobre o control plane. SARI-001 e SCORE-GEO-004 continuam calculados exclusivamente pelo core.</div>
</aside>
<main class="main">
  <div class="top"><div><h1 id="title">Visão geral</h1><div class="muted" id="identity">Conectando ao control plane…</div></div><div id="connection" class="status">verificando</div></div>
  <div id="message"></div>
  <div class="selectors">
    <label>Organização<select id="organization"></select></label>
    <label>Workspace<select id="workspace"></select></label>
    <label>Projeto<select id="project"></select></label>
    <label>Propriedade<select id="property"></select></label>
    <label>Ambiente<select id="environment"></select></label>
  </div>

  <section class="panel active" id="panel-overview">
    <div class="grid"><div class="card"><div class="muted">Auditorias</div><div class="metric" id="m-audits">—</div></div><div class="card"><div class="muted">Queries monitoradas</div><div class="metric" id="m-queries">—</div></div><div class="card"><div class="muted">Jobs ativos</div><div class="metric" id="m-jobs">—</div></div><div class="card"><div class="muted">Milestones</div><div class="metric" id="m-milestones">—</div></div></div>
    <div class="section-grid"><div class="card"><h2>Auditorias recentes</h2><div id="overview-audits"></div></div><div class="card"><h2>Estado operacional</h2><div id="overview-state" class="detail">Carregando…</div></div></div>
  </section>

  <section class="panel" id="panel-audits"><div class="section-grid"><div class="card"><h2>Histórico de auditorias</h2><div id="audits-table"></div></div><div class="card"><h2>Nova auditoria</h2><div class="form-grid"><label>Máximo de páginas<input id="audit-max-pages" type="number" min="1" max="100000" value="100"></label><label>Dispositivo<select id="audit-device"><option value="both">Mobile + Desktop</option><option value="mobile">Mobile</option><option value="desktop">Desktop</option></select></label><label>IA<select id="audit-ai"><option value="none">Sem IA</option><option value="auto">Auto</option><option value="openai">OpenAI</option><option value="deepseek">DeepSeek</option><option value="mimo">MiMo</option></select></label><label>Web Performance<select id="audit-performance"><option value="false">Não</option><option value="true">Sim</option></select></label><label class="full">Configuração AUDIT completa (JSON, sem credenciais)<textarea id="audit-config" rows="16" class="mono"></textarea><span>Carregada do contrato canônico; inclui Lighthouse, Apdex, Experience Apdex, IA e contexto de conteúdo.</span></label></div><div class="form-actions"><button class="btn primary" id="queue-audit">Enfileirar auditoria</button><button class="btn" id="reset-audit-config">Restaurar defaults</button></div><p class="muted">A API apenas cria o job. Execute um worker separado para processar a fila. Credenciais não pertencem ao payload e são rejeitadas.</p></div></div></section>

  <section class="panel" id="panel-search"><div class="card"><h2>Query Registry</h2><div id="search-table"></div></div></section>
  <section class="panel" id="panel-deployments"><div class="card"><h2>Milestones e comparação before/after</h2><div id="milestones-table"></div><h3 style="margin-top:16px">Par resolvido</h3><div class="detail" id="deployment-detail">Selecione um milestone.</div></div></section>
  <section class="panel" id="panel-jobs"><div class="card"><h2>Execution jobs</h2><div class="notice">Jobs permanecem duráveis no control plane. O browser nunca executa crawling diretamente.</div><div id="jobs-table"></div></div></section>
  <section class="panel" id="panel-usage"><div class="card"><h2>Uso e custo estimado</h2><div id="usage-table"></div></div></section>
</main></div>
<script>
const state={me:null,organizations:[],workspaces:[],projects:[],properties:[],environments:[],audits:[],queries:[],jobs:[],milestones:[],usage:[],auditDefaults:{}};
const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const short=value=>{const s=String(value??'—');return s.length>22?s.slice(0,10)+'…'+s.slice(-8):s};
const localHeader=()=>sessionStorage.getItem('rasai-dev-user')||'';
function authHeaders(extra={}){const headers={...extra};const user=localHeader();if(user)headers['x-rasai-user-id']=user;return headers}
async function api(path,options={}){const response=await fetch(path,{...options,headers:authHeaders(options.headers||{})});if(!response.ok){let detail='HTTP '+response.status;try{const body=await response.json();detail=body.detail||detail}catch{}throw new Error(detail)}const type=response.headers.get('content-type')||'';return type.includes('application/json')?response.json():response.text()}
function message(text,kind=''){ $('message').innerHTML=text?`<div class="notice ${kind}">${esc(text)}</div>`:'' }
function pill(status){const s=String(status||'UNKNOWN').toUpperCase();const klass=['SUCCEEDED','PASS','COMPLETED','SUCCESS','ACTIVE'].includes(s)?'good':['FAILED','FAIL','ERROR','CANCELLED'].includes(s)?'bad':['QUEUED','CLAIMED','RUNNING','PARTIAL'].includes(s)?'wait':'';return `<span class="pill ${klass}">${esc(status||'—')}</span>`}
function fillSelect(id,items,key,label){const el=$(id);const selected=el.value;el.innerHTML=items.map(x=>`<option value="${esc(x[key])}">${esc(label(x))}</option>`).join('');if(items.some(x=>String(x[key])===selected))el.value=selected;return el.value}
function table(headers,rows){if(!rows.length)return '<div class="empty">Nenhum dado disponível neste escopo.</div>';return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
function resetAuditConfig(){if($('audit-config'))$('audit-config').value=JSON.stringify(state.auditDefaults||{},null,2)}
async function connect(){try{state.me=await api('/api/v1/me');const [organizations,contract]=await Promise.all([api('/api/v1/organizations'),api('/api/v1/audit-job-options')]);state.organizations=organizations;state.auditDefaults=contract.defaults||{};resetAuditConfig();$('connection').textContent='conectado';$('connection').className='status ok';$('identity').textContent='Usuário '+state.me.user_id;await chooseOrganization()}catch(err){$('connection').textContent='autenticação necessária';$('connection').className='status warn';$('identity').textContent='A API está protegida.';renderDevLogin(err)}}
function renderDevLogin(err){$('message').innerHTML=`<div class="notice error">${esc(err.message)}<br><br>Em desenvolvimento local com <code>trusted-header</code>, informe um User ID existente. Em ambiente hospedado, o gateway deve injetar a identidade e este campo deve permanecer vazio.<div class="form-actions"><input id="dev-user" placeholder="USR-..." style="padding:8px;border:1px solid #d0d5dd;border-radius:8px"><button class="btn" id="dev-connect">Conectar localmente</button></div></div>`;$('dev-connect').onclick=()=>{const v=$('dev-user').value.trim();if(v){sessionStorage.setItem('rasai-dev-user',v);location.reload()}}}
async function chooseOrganization(){const orgId=fillSelect('organization',state.organizations,'organization_id',x=>x.name);if(!orgId)return clearScope();state.workspaces=await api(`/api/v1/organizations/${encodeURIComponent(orgId)}/workspaces`);await chooseWorkspace()}
async function chooseWorkspace(){const wsId=fillSelect('workspace',state.workspaces,'workspace_id',x=>x.name);if(!wsId)return clearProject();state.projects=await api(`/api/v1/workspaces/${encodeURIComponent(wsId)}/projects`);await chooseProject()}
async function chooseProject(){const projectId=fillSelect('project',state.projects,'project_id',x=>x.name);if(!projectId)return clearProject();state.properties=await api(`/api/v1/projects/${encodeURIComponent(projectId)}/properties`);await chooseProperty();await refreshProject()}
async function chooseProperty(){const propertyId=fillSelect('property',state.properties,'property_id',x=>x.name+' · '+x.hostname);if(!propertyId){state.environments=[];$('environment').innerHTML='';return}state.environments=await api(`/api/v1/properties/${encodeURIComponent(propertyId)}/environments`);fillSelect('environment',state.environments,'environment_id',x=>x.name+' · '+x.kind)}
function clearScope(){state.workspaces=[];clearProject();$('workspace').innerHTML=''}
function clearProject(){state.projects=[];state.properties=[];state.environments=[];['project','property','environment'].forEach(id=>$(id).innerHTML='')}
async function refreshProject(){const projectId=$('project').value,orgId=$('organization').value;if(!projectId)return;try{[state.audits,state.queries,state.jobs,state.milestones,state.usage]=await Promise.all([api(`/api/v1/projects/${encodeURIComponent(projectId)}/audits`),api(`/api/v1/projects/${encodeURIComponent(projectId)}/search-queries`),api(`/api/v1/projects/${encodeURIComponent(projectId)}/execution-jobs?limit=100`),api(`/api/v1/projects/${encodeURIComponent(projectId)}/milestones`),api(`/api/v1/organizations/${encodeURIComponent(orgId)}/usage`)]);renderAll()}catch(err){message(err.message,'error')}}
function renderAll(){const active=state.jobs.filter(j=>['QUEUED','CLAIMED','RUNNING'].includes(j.status));$('m-audits').textContent=state.audits.length;$('m-queries').textContent=state.queries.length;$('m-jobs').textContent=active.length;$('m-milestones').textContent=state.milestones.length;renderAudits();renderQueries();renderJobs();renderMilestones();renderUsage();$('overview-state').textContent=`Control plane: conectado\nProjeto: ${$('project').selectedOptions[0]?.textContent||'—'}\nPropriedade: ${$('property').selectedOptions[0]?.textContent||'—'}\nAmbiente: ${$('environment').selectedOptions[0]?.textContent||'—'}\nWorker: necessário para processar jobs enfileirados`;}
function renderAudits(){const rows=state.audits.map(a=>`<tr><td class="mono">${esc(short(a.audit_id))}</td><td>${esc(a.event_time)}</td><td>${pill(a.completion_status||a.status)}</td><td>${esc((a.scoring_versions||[]).join(', ')||'—')}</td><td>${esc(a.url_count)}</td><td><button class="btn js-report" data-audit="${esc(a.audit_id)}">Abrir relatório</button></td></tr>`);const html=table(['AUD','Data','Estado','Scoring','URLs','Ação'],rows);$('audits-table').innerHTML=html;$('overview-audits').innerHTML=table(['AUD','Data','Estado'],state.audits.slice(0,5).map(a=>`<tr><td class="mono">${esc(short(a.audit_id))}</td><td>${esc(a.event_time)}</td><td>${pill(a.completion_status||a.status)}</td></tr>`));document.querySelectorAll('.js-report').forEach(b=>b.onclick=()=>openReport(b.dataset.audit))}
function renderQueries(){const rows=state.queries.map(q=>`<tr><td>${esc(q.query)}</td><td>${esc(q.engine||q.provider||'—')}</td><td>${esc(q.domain_of_interest||'—')}</td><td>${pill(q.enabled===false?'DISABLED':'ACTIVE')}</td><td><button class="btn js-search-run" data-query="${esc(q.query_id)}" data-property="${esc(q.property_id)}" data-environment="${esc(q.environment_id)}">Executar</button></td></tr>`);$('search-table').innerHTML=table(['Query','Engine/Provider','Domínio','Estado','Ação'],rows);document.querySelectorAll('.js-search-run').forEach(b=>b.onclick=()=>queueSearch(b.dataset.query,b.dataset.property,b.dataset.environment))}
function renderJobs(){const rows=state.jobs.map(j=>`<tr><td class="mono">${esc(short(j.job_id))}</td><td>${esc(j.job_type)}</td><td>${pill(j.status)}</td><td>${esc(j.attempts)} / ${esc(j.max_attempts)}</td><td>${esc(j.created_at)}</td><td>${['QUEUED','CLAIMED','RUNNING'].includes(j.status)?`<button class="btn danger js-cancel" data-job="${esc(j.job_id)}">Cancelar</button>`:''}</td></tr>`);$('jobs-table').innerHTML=table(['Job','Tipo','Estado','Tentativas','Criado','Ação'],rows);document.querySelectorAll('.js-cancel').forEach(b=>b.onclick=()=>cancelJob(b.dataset.job))}
function renderMilestones(){const rows=state.milestones.map(m=>`<tr><td>${esc(m.title)}</td><td>${esc(m.kind)}</td><td>${esc(m.occurred_at)}</td><td>${esc(m.release||'—')}</td><td><button class="btn js-pair" data-milestone="${esc(m.milestone_id)}">Resolver par</button></td></tr>`);$('milestones-table').innerHTML=table(['Milestone','Tipo','Data','Release','Before/after'],rows);document.querySelectorAll('.js-pair').forEach(b=>b.onclick=()=>loadPair(b.dataset.milestone))}
function renderUsage(){const rows=state.usage.map(u=>`<tr><td>${esc(u.category)}</td><td>${esc(u.provider||'—')}</td><td>${esc(u.quantity)} ${esc(u.unit||'')}</td><td>${u.cost==null?'—':esc(u.cost)+' '+esc(u.currency||'')}</td></tr>`);$('usage-table').innerHTML=table(['Categoria','Provider','Quantidade','Custo estimado'],rows)}
async function queueAudit(){const projectId=$('project').value,propertyId=$('property').value,environmentId=$('environment').value;if(!projectId||!propertyId||!environmentId)return message('Selecione projeto, propriedade e ambiente.','error');try{let auditConfig=JSON.parse($('audit-config').value||'{}');if(!auditConfig||Array.isArray(auditConfig)||typeof auditConfig!=='object')throw new Error('Configuração AUDIT deve ser um objeto JSON.');auditConfig={...auditConfig,max_pages:Number($('audit-max-pages').value||100),device_context:$('audit-device').value,ai_provider:$('audit-ai').value,web_performance:$('audit-performance').value==='true'};const payload={property_id:propertyId,environment_id:environmentId,job_type:'AUDIT',payload:auditConfig,idempotency_key:'web-audit-'+Date.now()};await api(`/api/v1/projects/${encodeURIComponent(projectId)}/execution-jobs`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});message('Auditoria enfileirada. O worker separado processará o job.');await refreshProject();showPanel('jobs')}catch(err){message(err.message,'error')}}
async function queueSearch(queryId,propertyId,environmentId){try{await api(`/api/v1/projects/${encodeURIComponent($('project').value)}/execution-jobs`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({property_id:propertyId,environment_id:environmentId,job_type:'SEARCH_MONITOR',payload:{query_id:queryId},idempotency_key:'web-search-'+queryId+'-'+Date.now()})});message('Search Monitoring enfileirado.');await refreshProject();showPanel('jobs')}catch(err){message(err.message,'error')}}
async function cancelJob(jobId){try{await api(`/api/v1/execution-jobs/${encodeURIComponent(jobId)}/cancel`,{method:'POST'});await refreshProject()}catch(err){message(err.message,'error')}}
async function loadPair(id){try{const pair=await api(`/api/v1/milestones/${encodeURIComponent(id)}/deployment-pair?baseline_mode=AUTO`);$('deployment-detail').textContent=JSON.stringify(pair,null,2)}catch(err){$('deployment-detail').textContent=err.message}}
async function openReport(auditId,page='index.html',target=null){try{const base=`/api/v1/audits/${encodeURIComponent(auditId)}/reports/`;const [html,css]=await Promise.all([api(base+encodeURIComponent(page)),api(base+'css/site.css').catch(()=> '')]);let rendered=String(html);if(css){rendered=rendered.replace(/<link[^>]+href=["']css\/site\.css["'][^>]*>/i,`<style>${css}</style>`)}const bridge=`<script>document.addEventListener('click',function(e){var a=e.target.closest('a[href]');if(!a)return;var h=a.getAttribute('href')||'';if(/^[^:#?]+\\.html(?:[?#].*)?$/.test(h)){e.preventDefault();window.opener.rasaiReportNavigate(${JSON.stringify(auditId)},h.split(/[?#]/)[0],window)}});<\/script>`;rendered=rendered.replace('</body>',bridge+'</body>');const w=target||window.open('','_blank');if(!w)throw new Error('O navegador bloqueou a nova janela do relatório.');w.document.open();w.document.write(rendered);w.document.close()}catch(err){message('Não foi possível abrir o relatório: '+err.message,'error')}}
window.rasaiReportNavigate=(auditId,page,target)=>openReport(auditId,page,target);
function showPanel(name){document.querySelectorAll('.panel').forEach(p=>p.classList.toggle('active',p.id==='panel-'+name));document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.panel===name));$('title').textContent=document.querySelector(`#nav button[data-panel="${name}"]`)?.textContent||'RASAi'}
$('nav').onclick=e=>{const b=e.target.closest('button[data-panel]');if(b)showPanel(b.dataset.panel)};$('organization').onchange=chooseOrganization;$('workspace').onchange=chooseWorkspace;$('project').onchange=chooseProject;$('property').onchange=chooseProperty;$('environment').onchange=()=>{};$('queue-audit').onclick=queueAudit;$('reset-audit-config').onclick=resetAuditConfig;
setInterval(async()=>{if($('project').value&&state.me){try{state.jobs=await api(`/api/v1/projects/${encodeURIComponent($('project').value)}/execution-jobs?limit=100`);renderJobs();$('m-jobs').textContent=state.jobs.filter(j=>['QUEUED','CLAIMED','RUNNING'].includes(j.status)).length}catch{}}},6000);
connect();
</script>
</body></html>'''
